sys_ux_data_broker_transform.script:
function transform(input) {

    if (!input.quizSessionId) {
        return {
            success: false,
            message: "Quiz Session ID is required."
        };
    }

    var session = new GlideRecord("x_1892173_stopwa_0_quiz_session");

    if (!session.get(input.quizSessionId)) {
        return {
            success: false,
            message: "Quiz Session not found."
        };
    }

    var startTime = new GlideDateTime();

    session.setValue("run_start_time", startTime.getValue());

    var updated = session.update();

    return {
        success: !!updated,
        runStartTime: startTime.getValue(),
        sys_id: updated || ""
    };
}
